-- Research Plan confirmation (market-ai-orc, AI_REQUIRE_RESEARCH_PLAN_CONFIRMATION) and the named-period
-- return helper (AI_ENABLE_STANDARD_PERIOD_RETURN). Generated from the market-ai-orc tool definitions at be59c68.
-- 1. AI_research_run_audit accepts the run status AWAITING_CONFIRMATION and the response type
--    RESEARCH_PLAN_CONFIRMATION; without this the audit INSERT of a plan response fails its check constraints.
--    Existing rows are unchanged and satisfy the wider checks.
-- 2. Tool_Catalog: submit_data_need_spec v2 (inactive, like every market-ai-orc row), v1 superseded_by v2; run_python v1
--    records the period_return helper and its flag.
BEGIN;

DO $preflight$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ai_research_run_audit_status_check'
                   AND conrelid = 'public."AI_research_run_audit"'::regclass
                   AND pg_get_constraintdef(oid) NOT LIKE '%AWAITING_CONFIRMATION%') THEN
        RAISE EXCEPTION 'ai_research_run_audit_status_check is missing or already allows AWAITING_CONFIRMATION';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ai_research_run_audit_response_check'
                   AND conrelid = 'public."AI_research_run_audit"'::regclass
                   AND pg_get_constraintdef(oid) NOT LIKE '%RESEARCH_PLAN_CONFIRMATION%') THEN
        RAISE EXCEPTION 'ai_research_run_audit_response_check is missing or already allows RESEARCH_PLAN_CONFIRMATION';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'submit_data_need_spec' AND version = 'v1')
       OR EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'submit_data_need_spec' AND version = 'v2') THEN
        RAISE EXCEPTION 'Expected submit_data_need_spec v1 and no v2';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'run_python' AND version = 'v1'
                   AND tool_specific_limits->>'runtime_service' = 'market-ai-orc') THEN
        RAISE EXCEPTION 'Expected run_python v1 of market-ai-orc';
    END IF;
END;
$preflight$;

ALTER TABLE public."AI_research_run_audit"
    DROP CONSTRAINT ai_research_run_audit_status_check,
    ADD CONSTRAINT ai_research_run_audit_status_check
        CHECK (status IN ('COMPLETED', 'NEEDS_CLARIFICATION', 'AWAITING_CONFIRMATION', 'LIMITED', 'FAILED')),
    DROP CONSTRAINT ai_research_run_audit_response_check,
    ADD CONSTRAINT ai_research_run_audit_response_check
        CHECK (response_type IS NULL OR response_type IN ('ANSWER', 'CLARIFICATION', 'RESEARCH_PLAN_CONFIRMATION',
                                                          'LIMITATION'));

UPDATE public."Column_Catalog"
SET definition = CASE column_name
        WHEN 'status' THEN 'Run status returned to the caller: COMPLETED, NEEDS_CLARIFICATION, AWAITING_CONFIRMATION '
                           '(a Research Plan awaits the user''s approval), LIMITED or FAILED.'
        WHEN 'response_type' THEN 'ANSWER, CLARIFICATION, RESEARCH_PLAN_CONFIRMATION or LIMITATION; NULL for a failed '
                                  'run.'
    END,
    source_code_paths = array_append(source_code_paths, 'database/migrations/20260926_002_research_plan_confirmation.sql'),
    updated_at = CURRENT_TIMESTAMP
WHERE table_schema = 'public' AND table_name = 'AI_research_run_audit' AND column_name IN ('status', 'response_type');

UPDATE public."Table_Catalog"
SET source_code_paths = array_append(source_code_paths, 'database/migrations/20260926_002_research_plan_confirmation.sql'), updated_at = CURRENT_TIMESTAMP
WHERE table_schema = 'public' AND table_name = 'AI_research_run_audit';

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"superseded_by":"v2","superseded_note":"v2 adds the condition/outcome/baseline declarations to research_governance and the Research Plan guard"}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'submit_data_need_spec' AND version = 'v1';

UPDATE public."Tool_Catalog"
SET tool_specific_limits = tool_specific_limits || '{"standard_period_return":{"convention":"base = last valid value strictly before the range start; end = last valid value on or before the range end inside the range; return = end / base - 1, full precision","description_change":"With the flag on, the run_python description gains one sentence about the helper; the input schema is unchanged. The helper is listed by open_analysis_session in any case.","flag":"AI_ENABLE_STANDARD_PERIOD_RETURN","helper":"saniti.period_return(request, range_id, value_column=''close'', entity_column=None, date_column=None)","statuses":["COMPLETE","NO_PRIOR_CLOSE","NO_END_VALUE","INVALID_BASE_VALUE","INSUFFICIENT_INPUT_DATA","DUPLICATE_BOUNDARY_OBSERVATION"]}}'::jsonb, updated_at = CURRENT_TIMESTAMP
WHERE tool_name = 'run_python' AND version = 'v1' AND tool_specific_limits->>'runtime_service' = 'market-ai-orc';

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
VALUES
    ('submit_data_need_spec', 'ADVANCED', 'VALIDATION', 'Declare which data the answer needs (DataNeedSpec), before any extraction. It lists logical data requests and catalog relationships only: never a formula, indicator, method, ranking or output; all calculations are written later in the analysis session. Each data request names one catalog table, the columns needed, a scope (expression tree on filterable columns of that table: ALL, PREDICATE, AND/OR with children, NOT with child), one or more named time ranges (e.g. the current YTD and the same period last year), the source frequency and the analysis frequency (resample when coarser), history_buffer for warm-up observations before each range and future_buffer for observations after it, and ordering. Copy table names, entity/time columns, frequencies and subject from discover_catalog and get_catalog_details, and relationship ids and join semantics from the catalog relationships. A restriction by another table (for example prices of banks only) is a second data request on the reference table with its own scope, joined by an INNER relationship; never a manual ticker list. The validator answers APPROVED (need_id; next: prepare the data bundle), REVISION_REQUIRED (issues with data_request_id, code, field_path and rejected_value; fix each and resubmit with revision + 1, same request_group_id and data_request_ids), or CATALOG_UNAVAILABLE (stop and report temporarily). It never suggests a replacement: read the catalog again instead of guessing. mode RESEARCH also needs research_governance (hypothesis, objective, the condition, outcome and baseline as plain-language declarations, candidate_count, pairwise_comparisons, multiple_testing_policy, optional holdout range and minimum sample); the Research Governor answers APPROVED, REPLAN_REQUIRED or REJECTED with a reason code. When research needs an approved Research Plan, a RESEARCH submission without one, or one that differs from its approved experiment, is refused with RESEARCH_PLAN_* codes before anything is extracted. The same revision sent again returns the same answer.', '{"additionalProperties":false,"properties":{"data_requests":{"description":"1-8 logical data requests.","items":{"additionalProperties":false,"properties":{"analysis_frequency":{"description":"Frequency of the analysis (same as source, or coarser with resample).","type":"string"},"columns":{"description":"Catalog columns needed (entity and time columns are always added).","items":{"type":"string"},"type":"array"},"data_request_id":{"description":"<request_group_id>_<suffix>, suffix 1-12 letters/digits, e.g. data_request_1_A. Stable across revisions.","type":"string"},"entity_column":{"anyOf":[{"type":"string"},{"type":"null"}],"description":"The table''s catalog entity_column; null when it has none."},"future_buffer":{"anyOf":[{"additionalProperties":false,"properties":{"unit":{"enum":["TRADING_OBSERVATIONS","CALENDAR_DAYS"],"type":"string"},"value":{"type":"integer"}},"required":["value","unit"],"type":"object"},{"type":"null"}],"description":"Observations after each range (e.g. forward outcomes); null if none."},"history_buffer":{"anyOf":[{"additionalProperties":false,"properties":{"unit":{"enum":["TRADING_OBSERVATIONS","CALENDAR_DAYS"],"type":"string"},"value":{"type":"integer"}},"required":["value","unit"],"type":"object"},{"type":"null"}],"description":"Observations before each range needed as warm-up; null if none."},"logical_name":{"description":"Lower-case name the session loads the data by, e.g. prices.","type":"string"},"ordering":{"description":"Row order of the delivered dataset ([] for none).","items":{"additionalProperties":false,"properties":{"column":{"type":"string"},"direction":{"enum":["ASC","DESC"],"type":"string"}},"required":["column","direction"],"type":"object"},"type":"array"},"resample":{"anyOf":[{"enum":["DAILY","WEEKLY","MONTHLY","QUARTERLY","YEARLY"],"type":"string"},{"type":"null"}],"description":"Required when analysis_frequency is