     '{"description":"The DataNeedValidator result (model view): APPROVED with need_id, REVISION_REQUIRED with issues {data_request_id, code, field_path, rejected_value}, or CATALOG_UNAVAILABLE; the Research Governor decision. With Research Plan confirmation a RESEARCH submission may instead be REJECTED by market-ai-orc before the sandbox call, with error.code RESEARCH_PLAN_REQUIRED, RESEARCH_PLAN_TOKEN_INVALID, RESEARCH_PLAN_TOKEN_EXPIRED, RESEARCH_PLAN_MISMATCH or RESEARCH_PLAN_REAPPROVAL_REQUIRED and issues {experiment_id, field_path, rule, approved_value, submitted_value}.","properties":{"error":{},"extraction_allowed":{},"issues":{},"message":{},"need_id":{},"next_action":{},"replayed":{},"research_governance":{},"revision":{},"status":{},"warnings":{}},"type":"object"}'::jsonb,
     'ORCHESTRATOR', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 20000, 200, 20000, NULL,
     false, false, false, '{"executor_service":"market-python-sandbox","feature_flag":"AI_ENABLE_DATANEED","forbidden_content":["formulas","indicators","methods","rankings","outputs"],"handler":"app/tools/data_need.py","inner_relationship":"restricts both requests by the other request''s own scope (semi-join pushdown); the exact join runs in the analysis session","join_semantics":["CURRENT_STATE","EXACT_DATE","AS_OF","EFFECTIVE_DATED"],"join_semantics_source":"AI_catalog_relationships.supported_join_semantics (migration 20260925_003)","max_scope_depth":4,"modes":["ANALYSIS","RESEARCH"],"registry_state":"Registered in market-ai-orc only with AI_ENABLE_DATANEED; is_active=false keeps it out of market-ai-backend tool lists.","research_declarations":{"fields":["condition","outcome","baseline"],"meaning":"Plain-language declarations of the experiment, recorded and returned by the Research Governor; the backend never checks the analysis code against them.","sent_when":"non-null only (a sandbox without the fields accepts the request unchanged)"},"research_plan_guard":{"allowed_tightening":["fewer candidates","fewer pairwise comparisons","a larger minimum sample in the same unit","an added holdout"],"analysis_mode":"unaffected","codes":["RESEARCH_PLAN_REQUIRED","RESEARCH_PLAN_TOKEN_INVALID","RESEARCH_PLAN_TOKEN_EXPIRED","RESEARCH_PLAN_MISMATCH","RESEARCH_PLAN_REAPPROVAL_REQUIRED"],"exact_fields":["hypothesis_id","hypothesis","objective","condition","outcome","baseline","multiple_testing_policy"],"flag":"AI_REQUIRE_RESEARCH_PLAN_CONFIRMATION","rule":"A RESEARCH submission reaches the sandbox only with a verified user-approved Research Plan in the run and a research_governance declaration matching its experiment."},"revision_rules":"revision + 1 per resubmission; a catalog outage or REVISION_CONFLICT uses no revision","runtime_commit":"be59c68","runtime_service":"market-ai-orc","sandbox_endpoint":"POST /v1/data-needs","sandbox_flag":"PY_SANDBOX_DATANEED_ENABLED","server_supplied_fields":["request_id","reference_time","timezone"],"spec_version":"data_need_spec/v1","statuses":["APPROVED","REVISION_REQUIRED","CATALOG_UNAVAILABLE"],"validator_layers":["schema","catalog_binding","cross_request","planning_feasibility"]}'::jsonb, 'v2', false);

DO $verify$
BEGIN
    IF (SELECT count(*) FROM pg_constraint WHERE conrelid = 'public."AI_research_run_audit"'::regclass
          AND ((conname = 'ai_research_run_audit_status_check'
                AND pg_get_constraintdef(oid) LIKE '%AWAITING_CONFIRMATION%')
               OR (conname = 'ai_research_run_audit_response_check'
                   AND pg_get_constraintdef(oid) LIKE '%RESEARCH_PLAN_CONFIRMATION%'))) <> 2 THEN
        RAISE EXCEPTION 'The audit check constraints were not widened';
    END IF;
    IF (SELECT count(*) FROM public."Column_Catalog" WHERE table_name = 'AI_research_run_audit'
          AND column_name IN ('status', 'response_type') AND 'database/migrations/20260926_002_research_plan_confirmation.sql' = ANY(source_code_paths)) <> 2 THEN
        RAISE EXCEPTION 'Column_Catalog definitions of status and response_type were not updated';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'submit_data_need_spec' AND version = 'v2'
                   AND NOT is_active AND input_schema #> '{properties,research_governance,anyOf,0,properties}' ? 'baseline')
       OR (SELECT tool_specific_limits->>'superseded_by' FROM public."Tool_Catalog"
           WHERE tool_name = 'submit_data_need_spec' AND version = 'v1') IS DISTINCT FROM 'v2'
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'run_python' AND version = 'v1'
                      AND tool_specific_limits ? 'standard_period_return') THEN
        RAISE EXCEPTION 'Tool_Catalog registrations are incomplete';
    END IF;
END;
$verify$;

COMMIT;
